    int seed_multiplier = 100000;
    struct HyperParameters
    {
        int episodes;
        int seed;
        double alpha;
        double gamma;
    };

    std::vector<Episode> tile_coding(const std::vector<Feature> &features, const HyperParameters &hp, Config_TC &cfg_tc, const Config &cfg)
    {
        Env env(cfg);
        cfg_tc.alpha = hp.alpha;
        TileCoding q(cfg_tc);
        return train_loop(q, env, cfg, features, hp.gamma, hp.episodes, hp.seed);
    }
    std::vector<Row> tile_coding(const std::vector<Feature> &features, HyperParameters &hp, Config_TC &cfg_tc, const Config &cfg, int seed_count)
    {
        std::vector<Row> runs;
        for (int i = 0; i < seed_count; i++)
        {
            hp.seed = 10 + i * seed_multiplier;
            runs.push_back({"seed-" + std::to_string(hp.seed), tile_coding(features, hp, cfg_tc, cfg)});
        }
        for (const Row &r : runs)
        {
            print_row(r.name, r.eps);
            print_block_averages(r.eps); // [Claude]
        }
        return runs;
    }

    std::vector<Episode> rbf(const std::vector<Feature> &features, const HyperParameters &hp, Config_RBF &cfg_rbf, const Config &cfg)
    {
        Env env(cfg);
        cfg_rbf.alpha = hp.alpha;
        RadialBasisFunction q(cfg_rbf);
        return train_loop(q, env, cfg, features, hp.gamma, hp.episodes, hp.seed);
    }

    std::vector<Row> rbf(const std::vector<Feature> &features, HyperParameters &hp, Config_RBF &cfg_rbf, const Config &cfg, int seed_count)
    {
        std::vector<Row> runs;
        for (int i = 0; i < seed_count; i++)
        {
            hp.seed = 10 + i * seed_multiplier;
            runs.push_back({"seed-" + std::to_string(hp.seed), rbf(features, hp, cfg_rbf, cfg)});
        }

        for (const Row &r : runs)
        {
            print_row(r.name, r.eps);
            print_block_averages(r.eps); // [Claude]
        }

        return runs;
    }

    void tc_gamma_sweep(Config_TC &cfg_tc, Config &cfg)
    {
        HyperParameters hp{.episodes = 20000, .alpha = 0.1 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings), .gamma = 0.9};

        // 1.2.1 Start with 0.9
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-gamma-tune-0.9");
        // 1.2.2 Move to 0.99
        hp.gamma = 0.99;
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-gamma-tune-0.99");
        // 1.2.3 Try with 1
        hp.gamma = 1;
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-gamma-tune-1");
    }

    void tc_alpha_sweep(Config_TC &cfg_tc, Config &cfg)
    {
        HyperParameters hp{.episodes = 20000, .alpha = 0.05 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings), .gamma = 0.99};

        // 1.1.1 alpha = 0.1
        hp.alpha = 0.1 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.1");

        // 1.1.3 alpha = 0.3
        hp.alpha = 0.3 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.3");

        // 1.1.5 alpha = 0.5
        hp.alpha = 0.5 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.5");

        // 1.1.6 alpha = 0.6
        hp.alpha = 0.6 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.6");

        // 1.1.7 alpha = 0.7
        hp.alpha = 0.7 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.7");

        // 1.1.8 alpha = 0.8
        hp.alpha = 0.8 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings);
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-alpha-tune-0.8");
    }

    void tc_tile_sweep(Config_TC &cfg_tc, Config &cfg)
    {
        // optimal values found using last sweeps
        HyperParameters hp{.episodes = 20000, .alpha = 0.6 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings), .gamma = 0.99};

        // 1.3.1 Start with 1/100 resolution, tiles = 10
        cfg_tc.num_of_tiles = 10;
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-tile-tune-10");
        // 1.3.2 1/200, tiles=20
        cfg_tc.num_of_tiles = 20;
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-tile-tune-20");
        // 1.3.3 1/400, tiles=40
        cfg_tc.num_of_tiles = 40;
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-tile-tune-40");
    }

    void tc_cmp_keeper(Config_TC &cfg_tc, Config &cfg)
    {
        // optimal values found using last sweeps
        HyperParameters hp{.episodes = 20000, .alpha = 0.6 / (cfg_tc.num_of_state_variables * cfg_tc.num_of_tilings), .gamma = 0.99};
        cfg_tc.num_of_tiles = 20;

        cfg.keepers = {Controller::External, Controller::HandCoded, Controller::HandCoded};
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-keeper-tune-1");

        cfg.keepers = {Controller::External, Controller::External, Controller::External};
        save_csv(tile_coding(kFullFeatures, hp, cfg_tc, cfg, 3), "results/tc-keeper-tune-3");
    }

    void rbf_alpha_sweep(Config_RBF &cfg_rbf, Config &cfg)
    {
        HyperParameters hp{.episodes = 20000, .alpha = 0.4 / (cfg_rbf.num_of_state_variables), .gamma = 0.99};

        // alpha = 0.4
        save_csv(rbf(kFullFeatures, hp, cfg_rbf, cfg, 3), "results/rbf-alpha-tune-0.4");
        // alpha = 0.5
        hp.alpha = 0.5 / cfg_rbf.num_of_state_variables;
        save_csv(rbf(kFullFeatures, hp, cfg_rbf, cfg, 3), "results/rbf-alpha-tune-0.5");
        // alpha = 0.6
        hp.alpha = 0.6 / cfg_rbf.num_of_state_variables;
        save_csv(rbf(kFullFeatures, hp, cfg_rbf, cfg, 3), "results/rbf-alpha-tune-0.6");
        // alpha = 0.7
        hp.alpha = 0.7 / cfg_rbf.num_of_state_variables;
        save_csv(rbf(kFullFeatures, hp, cfg_rbf, cfg, 3), "results/rbf-alpha-tune-0.7");
    }

